-- =====================================================================
-- PROVENIENZE: DESCRIZIONI PIÙ CHIARE
-- Restano voci narrative (punto di partenza per il Master): non cambiano i tiri.
-- =====================================================================
update public.creation_options o
set description = v.descr
from (values
  ('Prima generazione al college', 'Sei il primo della tua famiglia ad andare al college. Nessuno a casa sa davvero cosa sia un GPA, una confraternita o un colloquio con il Dean: hai dovuto capire tutto da solo, e per questo hai una determinazione che gli altri si sognano. In cambio le regole non scritte del campus (borse, scadenze, chi conta e perché) per te sono una lingua straniera, e a volte la famiglia si aspetta più di quanto tu possa dare. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Figlio di papà', 'Sei cresciuto tra cene di beneficenza, club esclusivi e amici di famiglia con un cognome che apre le porte. Ti muovi a tuo agio con chi conta e sai come si parla a un professore o a un donatore. Però tutti sanno chi sono i tuoi genitori: molti ti giudicano prima di conoscerti, qualcuno ti cerca solo per quello, e dimostrare di valere qualcosa da solo è più difficile di quanto sembri. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Ragazzo di provincia', 'Vieni da una cittadina dove tutti si conoscono, la scuola era una sola e il sabato sera si passava al diner. Sei abituato alla vita all''aperto, alla fatica e a fidarti della parola data. San Diego però è un''altra cosa: il traffico, la gente che non saluta, i prezzi e le mode ti spiazzano, e all''inizio ti senti fuori posto anche quando non lo dai a vedere. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Cresciuto in una metropoli', 'Sei nato tra grattacieli, metropolitane e quartieri che non dormono mai. Sai muoverti ovunque, leggi la gente al volo e niente ti stupisce più di tanto. Il rovescio della medaglia è che i ritmi lenti ti stanno stretti: la tranquillità del campus ti annoia presto, e a volte scambi la diffidenza per furbizia. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Figlio di militari', 'Sei cresciuto seguendo i trasferimenti di un genitore nelle forze armate: una base dopo l''altra, una scuola nuova ogni due anni. Hai imparato ad adattarti in fretta, a rispettare le regole e a cavartela da solo. Però non hai mai avuto amicizie lunghe né una casa da chiamare tua: legarti alle persone ti costa, e quando qualcosa diventa stabile una parte di te aspetta già di ripartire. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Ex scuola privata', 'Hai frequentato una scuola privata esclusiva: classi piccole, professori brillanti, divise e un diploma che pesa. Arrivi al college con una preparazione solida e un metodo di studio che molti ti invidiano. In compenso ti porti addosso l''etichetta del privilegiato: c''è chi pensa che tu non abbia mai faticato, e il mondo fuori da quei cancelli a volte ti sorprende più di quanto vorresti. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Istruito a casa', 'Hai studiato a casa, seguito dalla famiglia o da tutor, con i tuoi tempi e i tuoi interessi. Sai organizzarti da solo, approfondire quello che ti appassiona e lavorare senza nessuno che ti controlli. La vita di gruppo invece è territorio sconosciuto: aule affollate, lavori di gruppo, feste e codici sociali del campus ti mettono a disagio, e capire come ci si fa degli amici è una materia tutta nuova. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Studente internazionale', 'Vieni da un altro paese e sei qui con un visto da studente. Porti con te un''altra lingua, un''altra cultura e contatti nel tuo paese d''origine che possono tornare utili. Però la famiglia è lontana, il fuso orario rende difficile sentirsi, e le differenze culturali (il modo di parlare, di scherzare, di stare insieme) a volte ti fanno sentire straniero anche in mezzo agli amici. È un punto di partenza per il Master: non cambia i tiri.')
,
  ('Studente adulto', 'Torni sui banchi dopo anni di lavoro, o ci arrivi più tardi degli altri. Hai esperienza di vita, sai gestire scadenze, soldi e responsabilità, e non ti fai impressionare da un professore severo. Però spesso sei il più grande della classe: le feste, i drammi e le priorità dei compagni non sono sempre i tuoi, e non sempre ti senti parte del gruppo. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Transfer student', 'Hai cominciato in un altro college (magari un community college vicino casa) e ti sei trasferito qui a percorso iniziato. Hai già visto come funziona un''università, sai cosa ti serve e cosa no. In compenso arrivi quando amicizie, confraternite e gruppi di studio sono già formati, e devi farti spazio in un ambiente che si conosce da anni. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Veterano', 'Hai servito nelle forze armate prima di iscriverti, magari con il GI Bill che ti paga gli studi. Hai disciplina, sangue freddo e un''idea molto chiara di cosa sia un problema vero. Proprio per questo i drammi del campus a volte ti sembrano piccoli, fai fatica a trovare chi ti capisce davvero, e certe esperienze del passato tornano quando meno te lo aspetti. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Cresciuto in affido', 'Sei passato da una famiglia affidataria all''altra, a volte da una casa famiglia, e hai imparato presto a contare su te stesso. Sai leggere le persone al volo e capisci quando qualcuno mente o sta per andarsene. Il rovescio è che fidarti ti costa moltissimo: tieni tutti a distanza, e quando qualcuno ti vuole bene davvero non sai bene cosa farne. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Figlio di immigrati', 'I tuoi genitori sono arrivati negli Stati Uniti da un altro paese e hanno fatto sacrifici enormi perché tu potessi studiare qui. Parli due lingue, vivi tra due culture e sai muoverti in entrambe. Però sulle tue spalle c''è il peso delle aspettative familiari: devi riuscire per te e per loro, e non sempre la tua strada coincide con quella che hanno immaginato. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Cresciuto in una comunità religiosa', 'Sei cresciuto in una comunità religiosa molto unita, con regole precise, riti condivisi e un forte senso di appartenenza. Hai valori saldi e sai da che parte stai. Il campus però è un mondo diverso: feste, libertà, idee e stili di vita che a casa erano impensabili mettono alla prova quello in cui credi, e a volte anche il rapporto con la tua famiglia. È un punto di partenza per il Master: non cambia i tiri.'),
  ('Famiglia di artisti girovaghi', 'Sei cresciuto in viaggio con una famiglia di artisti (circo, teatro, musica, spettacoli di strada), cambiando città di continuo. Hai talento per lo spettacolo, sai stare davanti a un pubblico e ti adatti a qualsiasi palco. In compenso non hai mai avuto regole fisse né una scuola tradizionale: orari, compiti e burocrazia del college sono una disciplina tutta da imparare. È un punto di partenza per il Master: non cambia i tiri.')
) as v (name, descr)
where o.name = v.name;
